CREATE TABLE IF NOT EXISTS awin_catalog_products (
  slug TEXT PRIMARY KEY, name TEXT NOT NULL, price NUMERIC NOT NULL,
  currency TEXT NOT NULL, brand TEXT NOT NULL, merchant TEXT NOT NULL,
  category TEXT NOT NULL, department TEXT NOT NULL, product_type TEXT NOT NULL,
  image_url TEXT NOT NULL, affiliate_url TEXT NOT NULL, description TEXT NOT NULL
);
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name, price=EXCLUDED.price, currency=EXCLUDED.currency, brand=EXCLUDED.brand, merchant=EXCLUDED.merchant, category=EXCLUDED.category, department=EXCLUDED.department, product_type=EXCLUDED.product_type, image_url=EXCLUDED.image_url, affiliate_url=EXCLUDED.affiliate_url, description=EXCLUDED.description;
